`timescale 1ns/1ps

// Generated by tools/build_order_font.py.
module order_hanzi_font_rom (
    input wire clk, input wire [5:0] phrase, input wire [4:0] character,
    input wire [4:0] row, output wire [31:0] bits
);
wire [7:0] glyph_stage;
reg [4:0] row_stage;
reg ext_stage;
reg ext2_stage;

// The phrase/character -> glyph table lives in a synchronous ROM whose
// registered output is the glyph stage. Glyphs 0-127 (127 blank) are in
// BRAM32K, glyphs 128-159 in a BRAM9K extension and 160-175 in a second
// extension (BRAM9K); one clock later the registered ext stages pick
// the bitmap that answered.
wire [10:0] glyph_address = {phrase, character};
wire [11:0] main_address = {glyph_stage[6:0], row_stage};
wire [9:0] ext_address = {glyph_stage[4:0], row_stage};
wire [31:0] main_bits;
wire [31:0] ext_bits;
wire [31:0] ext2_bits;
assign bits = ext2_stage ? ext2_bits : ext_stage ? ext_bits : main_bits;

always @(posedge clk) begin
    row_stage <= row;
    ext_stage <= glyph_stage[7] && !glyph_stage[5];
    ext2_stage <= glyph_stage[7] && glyph_stage[5];
end

`ifdef ORDER_UI_SIMULATION
reg [7:0] simulation_glyph [0:2047];
reg [7:0] simulation_glyph_stage;
reg [31:0] simulation_main [0:4095];
reg [31:0] simulation_ext [0:1023];
