reg [31:0] simulation_ext_bits;
reg [31:0] simulation_ext2 [0:511];
reg [31:0] simulation_ext2_bits;
initial $readmemh("../../project/rtl/display/order_hanzi_glyph.dath", simulation_glyph);
initial $readmemh("../../project/rtl/display/order_hanzi_font.dath", simulation_main);
initial $readmemh("../../project/rtl/display/order_hanzi_font_ext.dath", simulation_ext);
initial $readmemh("../../project/rtl/display/order_hanzi_font_ext2.dath", simulation_ext2);
always @(posedge clk) begin
    simulation_glyph_stage <= simulation_glyph[glyph_address];
    simulation_main_bits <= simulation_main[main_address];
    simulation_ext_bits <= simulation_ext[ext_address];
    simulation_ext2_bits <= simulation_ext2[ext_address[8:0]];
end
assign glyph_stage = simulation_glyph_stage;
assign main_bits = simulation_main_bits;
assign ext_bits = simulation_ext_bits;
assign ext2_bits = simulation_ext2_bits;
`else
EG_LOGIC_BRAM #(
